double maxMove = Tama.Args.Get(args, "maxMoveM", 0.1)/0.3048;
double step = Tama.Args.Get(args, "snapStepM", 0.5), tol = Tama.Args.Get(args, "snapTolMm", 5.0)/1000.0;
Func<XYZ,XYZ> flat = p => new XYZ(p.X, p.Y, 0);
Func<Curve,XYZ> cdir = c => (c.GetEndPoint(1) - c.GetEndPoint(0)).Normalize();
var plotParam = Tama.Args.Get(args, "plotParam", "Mark");
var summary = new List<object>();
foreach (var po in (object[])args["plots"]) {
  var pdict = (IDictionary<string,object>)po;
  int fid = Convert.ToInt32(pdict["floorId"]);
  var ids = ((object[])pdict["ids"]).Select(x => Convert.ToInt32(x)).ToList();
  var floor = doc.GetElement(new ElementId(fid)) as Floor;
  var sk = doc.GetElement(floor.SketchId) as Sketch;
  var plot = new List<Curve>(); foreach (CurveArray ca in sk.Profile) { foreach (Curve c in ca) plot.Add(c.CreateTransformed(Transform.CreateTranslation(new XYZ(0,0,-c.GetEndPoint(0).Z)))); break; }
  int n = plot.Count;
  if (ids.Count != n) throw new Exception("Floor " + fid + ": " + n + " edges but " + ids.Count + " lines");
  var unb = plot.Select(c => { var u = c.Clone(); u.MakeUnbound(); return u; }).ToList();
  var cen = plot.Select(c => c.GetEndPoint(0)).Aggregate(XYZ.Zero, (a,b) => a+b) / n;
  // match each line to an edge by direction, then proximity
  var lineEdge = new Dictionary<int,int>(); var edgeDist = new double[n]; var used = new HashSet<int>();
  var lines = ids.Select(id => doc.GetElement(new ElementId(id)) as CurveElement).ToList();
  var pairs = new List<Tuple<double,int,int,double>>();
  for (int li = 0; li < lines.Count; li++) { var c = lines[li].GeometryCurve; var m = flat(c.Evaluate(0.5,true)); var ld = cdir(c);
    for (int e = 0; e < n; e++) { double dot = Math.Abs(ld.DotProduct(cdir(plot[e]))); double d = unb[e].Project(m).Distance; pairs.Add(Tuple.Create((1 - dot) * 1000 + d, li, e, d)); } }
  var usedL = new HashSet<int>();
  foreach (var p in pairs.OrderBy(p => p.Item1)) { if (usedL.Contains(p.Item2) || used.Contains(p.Item3)) continue; usedL.Add(p.Item2); used.Add(p.Item3); lineEdge[p.Item2] = p.Item3; edgeDist[p.Item3] = p.Item4; }
  var dm = new double[n];
  for (int e = 0; e < n; e++) { double m = edgeDist[e]*0.3048; double r = Math.Round(m/step)*step; dm[e] = Math.Abs(m - r) <= tol ? r : Math.Round(m,3); }
  var offs = new List<Curve>();
  for (int e = 0; e < n; e++) { double d = dm[e]/0.3048; var o1 = plot[e].CreateOffset(d, XYZ.BasisZ); var o2 = plot[e].CreateOffset(-d, XYZ.BasisZ);
    var pick = o1.Evaluate(0.5,true).DistanceTo(cen) < o2.Evaluate(0.5,true).DistanceTo(cen) ? o1 : o2; var u = pick.Clone(); u.MakeUnbound(); offs.Add(u); }
  var corners = new List<XYZ>();
  for (int i = 0; i < n; i++) { IntersectionResultArray ira; offs[(i+n-1)%n].Intersect(offs[i], out ira);
    if (ira == null || ira.Size == 0) throw new Exception("Floor " + fid + ": no intersection at corner " + i);
    var orig = plot[i].GetEndPoint(0); XYZ best = null; foreach (IntersectionResult ir in ira) if (best == null || ir.XYZPoint.DistanceTo(orig) < best.DistanceTo(orig)) best = ir.XYZPoint; corners.Add(best); }
  var newEdges = new List<Curve>();
  for (int i = 0; i < n; i++) { var p0 = corners[i]; var p1 = corners[(i+1)%n]; newEdges.Add(offs[i] is Arc ? (Curve)Arc.Create(p0, p1, offs[i].Project((p0+p1)/2).XYZPoint) : Line.CreateBound(p0, p1)); }
  double maxMv = 0;
  for (int li = 0; li < lines.Count; li++) {
    var ce = lines[li]; var c = ce.GeometryCurve; double z = c.GetEndPoint(0).Z; var e = newEdges[lineEdge[li]]; var a0 = flat(c.GetEndPoint(0));
    bool same = e.GetEndPoint(0).DistanceTo(a0) <= e.GetEndPoint(1).DistanceTo(a0); var dz = new XYZ(0,0,z);
    var na = (same ? e.GetEndPoint(0) : e.GetEndPoint(1)) + dz; var nb = (same ? e.GetEndPoint(1) : e.GetEndPoint(0)) + dz;
    Curve nc = e is Arc ? (Curve)Arc.Create(na, nb, e.Evaluate(0.5,true) + dz) : Line.CreateBound(na, nb);
    double mv = Math.Max(c.GetEndPoint(0).DistanceTo(na), c.GetEndPoint(1).DistanceTo(nb));
    if (mv > maxMove) throw new Exception("Floor " + fid + ", line " + ce.Id.IntegerValue + " would move " + Math.Round(mv*304.8) + " mm; aborted.");
    maxMv = Math.Max(maxMv, mv); ce.SetGeometryCurve(nc, true);
  }
  summary.Add(new { plotId = floor.LookupParameter(plotParam)?.AsString(), floorId = fid, offsets_m = string.Join(" / ", dm.Select(d => d.ToString("0.###"))), maxMove_mm = Math.Round(maxMv*304.8,1) });
}
return summary;
